/**
 * Computes the bitwise set union of two or more Uint32Array bitmasks using
 * the Boolean-ring inclusion-exclusion identity.
 *
 * Mathematical identity:
 * In the Boolean ring (F_2^32, ^, &) generated by symmetric difference (XOR)
 * and intersection (AND), the union of two 32-bit bitmask words x and y has
 * the exact closed-form representation:
 *
 *   x ∪ y = x ⊕ y ⊕ (x ∧ y)
 *
 * (equivalently, via De Morgan's law, x ∪ y = ~((~x) ∧ (~y))).
 *
 * For a sequence of m >= 2 bitmasks A_0, A_1, ..., A_{m-1}, associativity of
 * the Boolean-ring union yields the iterative series recurrence per word i:
 *
 *   U_0[i] = A_0[i]
 *   U_k[i] = (U_{k-1}[i] ^ A_k[i] ^ (U_{k-1}[i] & A_k[i])) >>> 0,  k = 1..m-1
 *
 * which evaluates the full inclusion-exclusion union ⋃_{k=0}^{m-1} A_k without
 * mutating any input mask.
 *
 * @param {Uint32Array} a - First bitmask word array.
 * @param {Uint32Array} b - Second bitmask word array (same length as `a`).
 * @param {...Uint32Array} rest - Optional additional bitmask word arrays (each same length as `a`).
 * @returns {Uint32Array} A new Uint32Array containing the word-wise set union.
 * @throws {TypeError} If any argument is not an instance of Uint32Array.
 * @throws {RangeError} If any mask length differs from `a.length`.
 */
export function unionMask32Series(a, b, ...rest) {
	if (!(a instanceof Uint32Array)) {
		throw new TypeError('Expected first mask to be a Uint32Array')
	}
	if (!(b instanceof Uint32Array)) {
		throw new TypeError('Expected second mask to be a Uint32Array')
	}
	for (let j = 0; j < rest.length; j++) {
		if (!(rest[j] instanceof Uint32Array)) {
			throw new TypeError(`Expected mask at argument index ${j + 2} to be a Uint32Array`)
		}
	}

	const len = a.length
	if (b.length !== len) {
		throw new RangeError(`Mask length mismatch at argument index 1: expected ${len}, got ${b.length}`)
	}
	for (let j = 0; j < rest.length; j++) {
		if (rest[j].length !== len) {
			throw new RangeError(`Mask length mismatch at argument index ${j + 2}: expected ${len}, got ${rest[j].length}`)
		}
	}

	const out = new Uint32Array(len)

	if (rest.length === 0) {
		for (let i = 0; i < len; i++) {
			const x = a[i]
			const y = b[i]
			out[i] = (x ^ y ^ (x & y)) >>> 0
		}
		return out
	}

	for (let i = 0; i < len; i++) {
		const x = a[i]
		const y = b[i]
		let acc = (x ^ y ^ (x & y)) >>> 0
		for (let j = 0; j < rest.length; j++) {
			const w = rest[j][i]
			acc = (acc ^ w ^ (acc & w)) >>> 0
		}
		out[i] = acc
	}

	return out
}
